// ASK 227 rev 2: the HTTP node emits one item PER ROW (execution 36577), so rows come from every input item.
// The two older shapes (the whole array as one item, or an object with one key holding it) are still accepted.
const ins = $input.all().map(i => i.json);
let rows = [];
if (ins.length === 1 && Array.isArray(ins[0])) {
  rows = ins[0];
} else if (ins.length === 1 && ins[0] && typeof ins[0] === 'object' && !('table_name' in ins[0]) && Object.keys(ins[0]).length === 1) {
  rows = ins[0][Object.keys(ins[0])[0]] || [];
} else {
  rows = ins.filter(r => r && typeof r === 'object' && typeof r.table_name === 'string');
}
if (!rows || rows.length === 0) return [];
const grouped = {};
rows.forEach(r => {
  if (!grouped[r.table_name]) grouped[r.table_name] = [];
  grouped[r.table_name].push(r);
});
return Object.entries(grouped).map(([tableName, tableRows]) => ({
  json: {
    table_name: tableName,
    row_count: tableRows.length,
    rows: tableRows,
    snapshot_ts: new Date().toISOString()
  }
}));

// ASK 227: one file per table group. The RPC marks every fetched row exported, so every group must be written.
return $input.all().map(item => {
const d = item.json;
const ts = d.snapshot_ts;
const tableName = d.table_name;
let content = '# TRUTH App — Table Snapshot\n';
content += '## Table: ' + tableName + '\n';
content += '## Snapshot Time: ' + ts + '\n';
content += '## Change Count: ' + d.row_count + '\n';
content += '## Protected Table: YES — training knowledge target\n\n---\n\n';
d.rows.forEach((r, i) => {
  content += '### Change ' + (i+1) + ' — ' + r.operation + ' at ' + r.triggered_at + '\n';
  content += '```json\n' + JSON.stringify(r.changed_row, null, 2) + '\n```\n\n';
});
const filename = 'Snapshot_' + tableName + '_' + ts.replace(/[:.]/g, '-').replace('T', '_').substring(0, 19) + '.md';
return { json: { content, filename, table_name: tableName, snapshot_ts: ts } };
});

